import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

function invalid(message: string): never {
  throw new ApiError(400, 'VALIDATION_FAILED', message);
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function textOf(v: unknown, label: string, max: number): string {
  if (typeof v !== 'string' || v.trim() === '') {
    invalid(label + ' 값을 입력해 주세요.');
  }
  const text = (v as string).trim();
  if (text.length > max) {
    invalid(label + '은(는) ' + max + '자 이하여야 합니다.');
  }
  return text;
}

function idOf(v: unknown, label: string): string {
  const text = String(v);
  if (!/^[0-9]+$/.test(text)) {
    invalid(label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function amountOf(v: unknown): string {
  const text = String(v).trim();
  const num = Number(text);
  if (text === '' || !Number.isFinite(num) || num <= 0) {
    invalid('원인행위 금액은 0보다 큰 숫자여야 합니다.');
  }
  return text;
}

async function ensureRefs(
  db: Db,
  budgetItemId: string | null,
  purchaseRequestId: string | null,
  partnerId: string | null,
): Promise<void> {
  if (budgetItemId !== null) {
    const rows = await db.query(
      'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:id AS bigint)',
      { id: budgetItemId },
    );
    if (rows.length === 0) {
      invalid('예산과목을 찾을 수 없습니다.');
    }
  }
  if (purchaseRequestId !== null) {
    const rows = await db.query(
      'SELECT purchase_request_id FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint)',
      { id: purchaseRequestId },
    );
    if (rows.length === 0) {
      invalid('연결 품의서를 찾을 수 없습니다.');
    }
  }
  if (partnerId !== null) {
    const rows = await db.query(
      'SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)',
      { id: partnerId },
    );
    if (rows.length === 0) {
      invalid('거래처를 찾을 수 없습니다.');
    }
  }
}

function notFound(): never {
  throw new ApiError(404, 'COMMITMENT_NOT_FOUND', '원인행위를 찾을 수 없습니다.');
}

@Controller('api/v1')
export class FnSfr00403Controller {
  @Post('/commitments')
  @HttpCode(200)
  async createCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const commitmentType = textOf(data['commitmentType'], '원인행위 구분', 50);
    if (isBlank(data['budgetItemId'])) {
      invalid('예산과목을 선택해 주세요.');
    }
    const budgetItemId = idOf(data['budgetItemId'], '예산과목');
    const amount = amountOf(data['amount']);
    const purchaseRequestId = isBlank(data['purchaseRequestId'])
      ? null
      : idOf(data['purchaseRequestId'], '연결 품의서');
    const partnerId = isBlank(data['partnerId'])
      ? null
      : idOf(data['partnerId'], '거래처');
    return transaction(async (db) => {
      await ensureRefs(db, budgetItemId, purchaseRequestId, partnerId);
      // TODO: 예산잔액 초과 시 422 AMOUNT_EXCEEDS_BUDGET_BALANCE 차단 (예산 금액 출처 테이블이 입력에 없음)
      const rows = await db.query(
        'INSERT INTO commitment (commitment_type, budget_item_id, amount, purchase_request_id, partner_id, created_at, updated_at) '
          + 'VALUES (:commitmentType, CAST(:budgetItemId AS bigint), CAST(:amount AS numeric), '
          + 'CAST(:purchaseRequestId AS bigint), CAST(:partnerId AS bigint), now(), now()) '
          + 'RETURNING commitment_id AS "commitmentId", commitment_type AS "commitmentType", amount AS "amount"',
        { commitmentType, budgetItemId, amount, purchaseRequestId, partnerId },
      );
      return rows[0];
    });
  }

  @Get('/commitments')
  async listCommitments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageRaw = isBlank(query['page']) ? '0' : String(query['page']);
    const sizeRaw = isBlank(query['size']) ? String(DEFAULT_SIZE) : String(query['size']);
    if (!/^[0-9]+$/.test(pageRaw) || !/^[0-9]+$/.test(sizeRaw)) {
      invalid('page, size 값이 올바르지 않습니다.');
    }
    const page = Number(pageRaw);
    const size = Math.min(Math.max(Number(sizeRaw), 1), MAX_SIZE);
    const budgetItemId = isBlank(query['budgetItemId'])
      ? null
      : idOf(query['budgetItemId'], '예산과목');
    const commitmentType = isBlank(query['commitmentType'])
      ? null
      : String(query['commitmentType']);
    return transaction(async (db) => {
      const where = '(CAST(:budgetItemId AS bigint) IS NULL OR budget_item_id = CAST(:budgetItemId AS bigint)) '
        + 'AND (CAST(:commitmentType AS varchar) IS NULL OR commitment_type = CAST(:commitmentType AS varchar))';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM commitment WHERE ' + where,
        { budgetItemId, commitmentType },
      );
      const items = await db.query(
        'SELECT commitment_id AS "commitmentId", commitment_type AS "commitmentType", '
          + 'budget_item_id AS "budgetItemId", amount AS "amount" '
          + 'FROM commitment WHERE ' + where
          + ' ORDER BY commitment_id DESC LIMIT :size OFFSET :offset',
        { budgetItemId, commitmentType, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Patch('/commitments/:commitmentId')
  @HttpCode(200)
  async updateCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['commitmentId'];
    const data = checks.inputOf(req.body);
    const commitmentType = isBlank(data['commitmentType'])
      ? null
      : textOf(data['commitmentType'], '원인행위 구분', 50);
    const budgetItemId = isBlank(data['budgetItemId'])
      ? null
      : idOf(data['budgetItemId'], '예산과목');
    const amount = isBlank(data['amount']) ? null : amountOf(data['amount']);
    const purchaseRequestId = isBlank(data['purchaseRequestId'])
      ? null
      : idOf(data['purchaseRequestId'], '연결 품의서');
    const partnerId = isBlank(data['partnerId'])
      ? null
      : idOf(data['partnerId'], '거래처');
    if (!/^[0-9]+$/.test(id)) {
      notFound();
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT commitment_id FROM commitment WHERE commitment_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        notFound();
      }
      await ensureRefs(db, budgetItemId, purchaseRequestId, partnerId);
      // TODO: 예산잔액 초과 시 422 AMOUNT_EXCEEDS_BUDGET_BALANCE 차단 (예산 금액 출처 테이블이 입력에 없음)
      const rows = await db.query(
        'UPDATE commitment SET '
          + 'commitment_type = COALESCE(CAST(:commitmentType AS varchar), commitment_type), '
          + 'budget_item_id = COALESCE(CAST(:budgetItemId AS bigint), budget_item_id), '
          + 'amount = COALESCE(CAST(:amount AS numeric), amount), '
          + 'purchase_request_id = COALESCE(CAST(:purchaseRequestId AS bigint), purchase_request_id), '
          + 'partner_id = COALESCE(CAST(:partnerId AS bigint), partner_id), '
          + 'updated_at = now() '
          + 'WHERE commitment_id = CAST(:id AS bigint) '
          + 'RETURNING commitment_id AS "commitmentId", amount AS "amount"',
        { id, commitmentType, budgetItemId, amount, purchaseRequestId, partnerId },
      );
      return rows[0];
    });
  }

  @Delete('/commitments/:commitmentId')
  async deleteCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['commitmentId'];
    if (!/^[0-9]+$/.test(id)) {
      notFound();
    }
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM commitment WHERE commitment_id = CAST(:id AS bigint)',
        { id },
      );
      if (count === 0) {
        notFound();
      }
      return {};
    });
  }
}

