import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

type Mode = { kind: 'create' } | { kind: 'edit'; row: Row } | { kind: 'delete'; row: Row } | null;

function blank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

export default function FnSfr00403Page({ role, notify }: PageProps) {
  const [draftBudget, setDraftBudget] = useState<number | string>('');
  const [draftType, setDraftType] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/commitments', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const rows = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = rows.reduce((sum, r) => sum + Number(r['amount'] ?? 0), 0);

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function openCreate() {
    setForm({});
    setMode({ kind: 'create' });
  }

  function openEdit(row: Row) {
    setForm({
      commitmentType: row['commitmentType'],
      budgetItemId: row['budgetItemId'],
      amount: row['amount'],
    });
    setMode({ kind: 'edit', row });
  }

  function search() {
    setPage(0);
    setApplied({ budgetItemId: draftBudget, commitmentType: draftType });
  }

  function reset() {
    setDraftBudget('');
    setDraftType('');
    setPage(0);
    setApplied({});
  }

  function validate(requireAll: boolean) {
    if (requireAll && blank(form['commitmentType'])) {
      throw new Error('원인행위 구분을 입력해 주세요.');
    }
    if (requireAll && blank(form['budgetItemId'])) {
      throw new Error('예산과목을 선택해 주세요.');
    }
    if (requireAll && blank(form['amount'])) {
      throw new Error('원인행위 금액을 입력해 주세요.');
    }
  }

  async function submitCreate() {
    validate(true);
    await call('POST', '/commitments', role, {
      commitmentType: form['commitmentType'],
      budgetItemId: form['budgetItemId'],
      amount: form['amount'],
      purchaseRequestId: blank(form['purchaseRequestId']) ? undefined : form['purchaseRequestId'],
      partnerId: blank(form['partnerId']) ? undefined : form['partnerId'],
    });
    notify('원인행위를 등록했습니다.');
    setMode(null);
    reload();
  }

  async function submitEdit(row: Row) {
    validate(false);
    await call('PATCH', '/commitments/' + String(row['commitmentId']), role, {
      commitmentType: form['commitmentType'],
      budgetItemId: form['budgetItemId'],
      amount: form['amount'],
      purchaseRequestId: blank(form['purchaseRequestId']) ? undefined : form['purchaseRequestId'],
      partnerId: blank(form['partnerId']) ? undefined : form['partnerId'],
    });
    notify('원인행위를 수정했습니다.');
    setMode(null);
    reload();
  }

  async function submitDelete(row: Row) {
    await call('DELETE', '/commitments/' + String(row['commitmentId']), role);
    notify('원인행위를 삭제했습니다.');
    setMode(null);
    reload();
  }

  const columns = [
    { key: 'commitmentId', label: '원인행위 ID' },
    { key: 'commitmentType', label: '원인행위 구분' },
    {
      key: 'budgetItemId',
      label: '예산과목',
      render: (r: Row) => <RefName table="budget_item" role={role} value={r['budgetItemId']} />,
    },
    { key: 'amount', label: '원인행위 금액', render: (r: Row) => <Num value={r['amount']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          <button type="button" onClick={() => openEdit(r)}>수정</button>
          <button type="button" onClick={() => setMode({ kind: 'delete', row: r })}>삭제</button>
        </span>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>원인행위 현황</h2>
        <Tiles
          items={[
            ['전체 건수', <Num value={total} />],
            ['현재 쪽 금액 합계', <Num value={pageSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>원인행위 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="예산과목">
            <LookupSelect
              table="budget_item"
              role={role}
              value={draftBudget}
              onChange={setDraftBudget}
              placeholder="전체"
            />
          </Field>
          <Field label="원인행위 구분">
            <TextInput value={draftType} onChange={setDraftType} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>원인행위 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable columns={columns} rows={rows} empty="원인행위가 없습니다." />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      {mode && mode.kind === 'create' ? (
        <Drawer title="원인행위 등록" onClose={() => setMode(null)}>
          <Form onSubmit={submitCreate} submit="저장">
            <Field label="원인행위 구분" required>
              <TextInput value={form['commitmentType']} onChange={(v) => setField('commitmentType', v)} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect
                table="budget_item"
                role={role}
                value={form['budgetItemId']}
                onChange={(v) => setField('budgetItemId', v)}
              />
            </Field>
            <Field label="원인행위 금액" required>
              <NumberInput value={form['amount']} onChange={(v) => setField('amount', v)} />
            </Field>
            <Field label="연결 품의서">
              <LookupSelect
                table="purchase_request"
                role={role}
                value={form['purchaseRequestId']}
                onChange={(v) => setField('purchaseRequestId', v)}
              />
            </Field>
            <Field label="거래처">
              <LookupSelect
                table="partner"
                role={role}
                value={form['partnerId']}
                onChange={(v) => setField('partnerId', v)}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode && mode.kind === 'edit' ? (
        <Drawer title="원인행위 수정" onClose={() => setMode(null)}>
          <Form onSubmit={() => submitEdit(mode.row)} submit="수정">
            <Field label="원인행위 구분">
              <TextInput value={form['commitmentType']} onChange={(v) => setField('commitmentType', v)} />
            </Field>
            <Field label="예산과목">
              <LookupSelect
                table="budget_item"
                role={role}
                value={form['budgetItemId']}
                onChange={(v) => setField('budgetItemId', v)}
              />
            </Field>
            <Field label="원인행위 금액">
              <NumberInput value={form['amount']} onChange={(v) => setField('amount', v)} />
            </Field>
            <Field label="연결 품의서">
              <LookupSelect
                table="purchase_request"
                role={role}
                value={form['purchaseRequestId']}
                onChange={(v) => setField('purchaseRequestId', v)}
              />
            </Field>
            <Field label="거래처">
              <LookupSelect
                table="partner"
                role={role}
                value={form['partnerId']}
                onChange={(v) => setField('partnerId', v)}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode && mode.kind === 'delete' ? (
        <Drawer title="원인행위 삭제" onClose={() => setMode(null)}>
          <Form
            onSubmit={() => submitDelete(mode.row)}
            submit="삭제"
            danger
            note={'원인행위 ' + String(mode.row['commitmentId']) + '번을 삭제합니다.'}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
